// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, address actor) public {
        // Widen the admissible domain: actor must not be the test contract or c itself
        vm.assume(actor != address(c) && actor != address(this));

        // Deploy and wire the log file (required setup)
        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        // Fund the actor with enough ether for the deposit
        depositAmt = bound(depositAmt, 1, address(this).balance > 0 ? address(this).balance : 1);
        vm.deal(actor, depositAmt);

        // Actor deposits
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        uint256 balBefore = c.balances(actor);

        // Collect amount must be within balance; if not, Collect is a no-op and balances stay same
        if (collectAmt <= balBefore) {
            vm.prank(actor);
            (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));
            if (ok) {
                // Reference: balances[actor] = balBefore - collectAmt -> never increases
                // Mutant:    balances[actor] = balBefore + collectAmt -> increases (balBefore + collectAmt > balBefore)
                // Also the ether transferred out is collectAmt, so contract balance decreases by collectAmt in both.
                // Rule: after Collect, the recorded balances[actor] must be <= balBefore.
                uint256 balAfter = c.balances(actor);
                assertTrue(balAfter <= balBefore);
            }
        }
    }
}

contract LogFile {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
